function Main-Menu { Show-Banner; Write-Host " UNDO ALL CHANGES (Go Back to Normal)" -ForegroundColor DarkGray; Write-Host " LAPTOP TUNING ENGINE" -ForegroundColor Yellow; Write-Host " DESKTOP TUNING ENGINE" -ForegroundColor Red; Write-Host " DEEP WINDOWS DEBLOAT & AI REMOVER" -ForegroundColor Magenta; Write-Host ""; $choice = Read-Host " 👉 CHOOSE YOUR HARDWARE TYPE"; switch ($choice) { "1" { Laptop-Menu } "2" { Desktop-Menu } "3" { Windows-Debloat; Main-Menu } "0" { Undo-Changes; Main-Menu } default { Main-Menu } } }
function Laptop-Menu { Show-Banner; Write-Host " 💻 [LAPTOP MODE ACTIVE]" -ForegroundColor Yellow; Write-Host " ---------------------------------------" -ForegroundColor Cyan; Write-Host " CPU OPTIMIZATIONS" -ForegroundColor White; Write-Host " GPU AUTOMATION" -ForegroundColor White; Write-Host " COMPETITIVE GAME PROFILES" -ForegroundColor White; Write-Host " ZERO-DELAY NETWORK ENGINE" -ForegroundColor White; Write-Host " [B] BACK TO MAIN MENU" -ForegroundColor DarkGray; Write-Host ""; $choice = Read-Host " 👉 ENTER CHOICE"; switch ($choice) { "1" { Laptop-CPU; Laptop-Menu } "2" { Automated-GPU; Laptop-Menu } "3" { Games-Menu; Laptop-Menu } "4" { Network-Engine; Laptop-Menu } "b" { Main-Menu } default { Laptop-Menu } } }
function Desktop-Menu { Show-Banner; Write-Host " 🖥️ [DESKTOP MODE ACTIVE]" -ForegroundColor Red; Write-Host " ---------------------------------------" -ForegroundColor Cyan; Write-Host " CPU OPTIMIZATIONS" -ForegroundColor White; Write-Host " GPU AUTOMATION" -ForegroundColor White; Write-Host " COMPETITIVE GAME PROFILES" -ForegroundColor White; Write-Host " ZERO-DELAY NETWORK ENGINE" -ForegroundColor White; Write-Host " [B] BACK TO MAIN MENU" -ForegroundColor DarkGray; Write-Host ""; $choice = Read-Host " 👉 ENTER CHOICE"; switch ($choice) { "1" { Desktop-CPU; Desktop-Menu } "2" { Automated-GPU; Desktop-Menu } "3" { Games-Menu; Desktop-Menu } "4" { Network-Engine; Desktop-Menu } "b" { Main-Menu } default { Desktop-Menu } } }
function Laptop-CPU { Show-Banner; Write-Host " SAFE TWEAK: Optimize Thread Efficiency" -ForegroundColor Green; Write-Host " ADVANCED TWEAK: Force 100% Core Unpark" -ForegroundColor Red; Write-Host " [B] GO BACK" -ForegroundColor DarkGray; Write-Host ""; $c = Read-Host " 👉 SELECT ACTION"; if ($c -eq "1") { Powercfg -setacvalueindex scheme_current sub_processor CPMINCORES 100; Powercfg -setactive scheme_current; Write-Host "[✓] Safe Laptop Profile Loaded!" -ForegroundColor Green; Start-Sleep 2 } elseif ($c -eq "2") { reg add "HKLM\SYSTEM\CurrentControlSet\Control\Power\PowerSettings\545335f6-bdd1-40be-a9ed-c4d447d3d4b6\0cc5b647-c1df-4637-891a-dec35c318583" /v ValueMax /t REG_DWORD /d 0 /f; Write-Host "[✓] Hyper-Aggressive Unparking Forced!" -ForegroundColor Red; Start-Sleep 2 } }
function Desktop-CPU { Show-Banner; Write-Host " SAFE TWEAK: Optimize Core Scheduling Priorities" -ForegroundColor Green; Write-Host " ADVANCED TWEAK: Disable Power Throttling Entirely" -ForegroundColor Red; Write-Host " [B] GO BACK" -ForegroundColor DarkGray; Write-Host ""; $c = Read-Host " 👉 SELECT ACTION"; if ($c -eq "1") { reg add "HKLM\SYSTEM\CurrentControlSet\Control\PriorityControl" /v Win32PrioritySeparation /t REG_DWORD /d 38 /f; Write-Host "[✓] Thread Priority Optimized!" -ForegroundColor Green; Start-Sleep 2 } elseif ($c -eq "2") { reg add "HKLM\SYSTEM\CurrentControlSet\Control\Power" /v PowerThrottlingOff /t REG_DWORD /d 1 /f; Write-Host "[✓] CPU Power Constraints Fully Melted!" -ForegroundColor Red; Start-Sleep 2 } }
function Automated-GPU { Show-Banner; Write-Host "[+] FORCING GPU REAL-TIME PRIORITIZATION..." -ForegroundColor Cyan; reg add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" /v "GPU Priority" /t REG_DWORD /d 8 /f; reg add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" /v "Priority" /t REG_DWORD /d 6 /f; reg add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" /v "Scheduling Category" /t REG_SZ /d "High" /f; Write-Host "[✓] Your GPU is now locked to maximum performance priority!" -ForegroundColor Green; Start-Sleep 2 }
function Network-Engine { Show-Banner; Write-Host "[+] REMOVING NETWORKING DELAYS & PING SPIKES..." -ForegroundColor Cyan; reg add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" /v NetworkThrottlingIndex /t REG_DWORD /d 4294967295 /f; $interfaces = Get-ChildItem "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"; foreach ($i in $interfaces) { $path = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\$($i.PSChildName)"; Set-ItemProperty -Path $path -Name "TcpAckFrequency" -Value 1 -Type DWord -ErrorAction SilentlyContinue; Set-ItemProperty -Path $path -Name "TCPNoDelay" -Value 1 -Type DWord -ErrorAction SilentlyContinue }; Write-Host "[✓] Wi-Fi and Ethernet packet delays eliminated!" -ForegroundColor Green; Start-Sleep 2 }
function Games-Menu { Show-Banner; Write-Host " 🎮 GAME PROFILE CHOOSE ENGINE" -ForegroundColor Cyan; Write-Host " ---------------------------------------" -ForegroundColor Cyan; Write-Host " FORTNITE" -ForegroundColor White; Write-Host " VALORANT" -ForegroundColor White; Write-Host " COUNTER-STRIKE 2" -ForegroundColor White; Write-Host " ROBLOX" -ForegroundColor White; Write-Host " MINECRAFT" -ForegroundColor White; Write-Host " [B] GO BACK" -ForegroundColor DarkGray; Write-Host ""; $g = Read-Host " 👉 SELECT YOUR GAME"; switch ($g) { "1" { powershell -Command "Set-ProcessMitigation -Name FortniteClient-Win64-Shipping.exe -Disable ControlFlowGuard"; Write-Host "[✓] Fortnite Delay Mitigations Removed!" -ForegroundColor Green; Start-Sleep 2 } "2" { powershell -Command "Set-ProcessMitigation -Name VALORANT-Win64-Shipping.exe -Disable ControlFlowGuard"; Write-Host "[✓] Valorant Process Priority Set to Extreme!" -ForegroundColor Green; Start-Sleep 2 } "3" { powershell -Command "Set-ProcessMitigation -Name cs2.exe -Disable ControlFlowGuard"; Write-Host "[✓] CS2 Micro-Stutters Fixed!" -ForegroundColor Green; Start-Sleep 2 } "4" { reg add "HKCU\Software\Roblox\Client" /v "FFlagDebugGraphicsDisableDirect3D11" /t REG_DWORD /d 0 /f; Write-Host "[✓] Roblox Render Buffer Pipeline Optimized!" -ForegroundColor Green; Start-Sleep 2 } "5" { [Environment]::SetEnvironmentVariable("_JAVA_OPTIONS", "-XX:+UseG1GC -XX:+ParallelRefProcEnabled -XX:MaxGCPauseMillis=200", "User"); Write-Host "[✓] Minecraft Java Garbage Collection Tweaked (Smooth FPS)!" -ForegroundColor Green; Start-Sleep 2 } "b" { return } } }
function Windows-Debloat { Show-Banner; Write-Host "[+] REMOVING HEAVY WINDOWS AI & BACKGROUND TELEMETRY..." -ForegroundColor Magenta; Stop-Service -Name "DiagTrack" -Force -ErrorAction SilentlyContinue; Set-Service -Name "DiagTrack" -StartupType Disabled -ErrorAction SilentlyContinue; reg add "HKCU\Software\Microsoft\Windows\CurrentVersion\Feeds" /v ShellFeedsTaskbarViewMode /t REG_DWORD /d 2 /f; reg add "HKCU\Software\Microsoft\Windows\CurrentVersion\GameDVR" /v "AppCaptureEnabled" /t REG_DWORD /d 0 /f; Write-Host "[✓] Windows system overhead heavily cleared out!" -ForegroundColor Green; Start-Sleep 2 }
function Undo-Changes { Show-Banner; Write-Host "[+] REVERTING ALL SETTINGS BACK TO WINDOWS STANDARD..." -ForegroundColor Yellow; reg add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" /v NetworkThrottlingIndex /t REG_DWORD /d 10 /f; reg add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" /v "GPU Priority" /t REG_DWORD /d 8 /f; reg add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" /v "Priority" /t REG_DWORD /d 2 /f; reg add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" /v "Scheduling Category" /t REG_SZ /d "Medium" /f; reg delete "HKLM\SYSTEM\CurrentControlSet\Control\Power" /v PowerThrottlingOff /f -ErrorAction SilentlyContinue; Write-Host "[✓] All settings reverted back to normal. Run the tool again anytime!" -ForegroundColor Green; Start-Sleep 3 }Main-Menu